def lang():
    """'vi' when ONECREW_LANG=vi, else 'en'."""
    return 'vi' if os.environ.get('ONECREW_LANG', '').strip().lower() == 'vi' else 'en'


def t(key, **values):
    """The text of `key` in the current language, with {name} placeholders filled."""
    return TEXT[key][lang()].format(**values)
